+use crate::prelude::*;
+use biome_formatter::write;
+use biome_markdown_syntax::MdCodeNameList;
+#[derive(Debug, Clone, Default)]
+pub(crate) struct FormatMdCodeNameList;
+impl FormatRule<MdCodeNameList> for FormatMdCodeNameList {
+    type Context = MarkdownFormatContext;
+    fn fmt(&self, node: &MdCodeNameList, f: &mut MarkdownFormatter) -> FormatResult<()> {
+        // Collect the tokens that make up the info string. The info string may
+        // be split across several `MdTextual` tokens (e.g. `rust,ignore` where
+        // the comma splits tokens), so it is reassembled here before printing.
+        // Because the tokens are printed manually rather than through each
+        // `MdTextual`'s format rule, their suppression state is marked as
+        // checked here to satisfy the formatter's bookkeeping.
+        let comments = f.comments().clone();
+        let tokens: Vec<_> = node
+            .iter()
+            .inspect(|textual| comments.mark_suppression_checked(textual.syntax()))
+            .filter_map(|textual| textual.value_token().ok())
+            .collect();
+
+        if tokens.is_empty() {
+            return Ok(());
+        }
+
+        // Reassemble the raw info string. Internal structure (commas, runs of
+        // whitespace between values) is preserved so tags like
+        // `rust,  ignore   expect_diagnostics` keep their meaning.
+        let mut info_string = String::new();
+        for token in &tokens {
+            info_string.push_str(token.text());
+        }
+
+        // Trim surrounding whitespace: the info string must sit flush against
+        // the opening fence (no leading space), and any trailing whitespace
+        // before the newline (or end of input) is insignificant. Whitespace
+        // *within* the info string is preserved by only trimming the ends.
+        let trimmed = info_string.trim();
+
+        // The first token stands in for the whole info string; the remaining
+        // tokens are removed since their text has already been captured above.
+        let (first, rest) = tokens.split_first().expect("tokens is non-empty");
+
+        if trimmed.is_empty() {
+            write!(f, [format_removed(first)])?;
+        } else {
+            write!(
+                f,
+                [format_replaced(
+                    first,
+                    &text(trimmed, first.text_trimmed_range().start())
+                )]
+            )?;
+        }
+
+        for token in rest {
+            write!(f, [format_removed(token)])?;
+        }
+
+        Ok(())
+    }
+}
